                <h3 className="plan-card-title">{getPlanDisplayName(plan)}</h3>
              </Link>
              <p className="muted">{getPlanReviewReason(plan)}</p>
            </div>
            <div className="plan-history-meta">
              <Link href={`/plans/${plan.plan_id}?review_required=1`} className="ghost-button">
                Review hold
              </Link>
            </div>
          </div>
        ))}
      </div>

      {remainingCount > 0 ? (
        <p className="muted">
          {remainingCount} more held plan{remainingCount === 1 ? "" : "s"} shown in saved plan history.
        </p>
      ) : null}
    </article>
  );
}

function PlansSyncState() {
  return (
    <article className="list-card plans-sync-card" aria-busy="true">
      <div className="plans-dashboard-card-header">
        <div className="plans-dashboard-card-copy">
          <p className="kicker">Plan sync</p>
          <h2>Loading saved fight camps</h2>
          <p className="muted">
            One moment.
          </p>
        </div>
        <span className="badge status-badge-neutral">Syncing</span>
      </div>
      <div className="plans-sync-grid" aria-hidden="true">
        <div className="plans-sync-line plans-sync-line-short" />
        <div className="plans-sync-line" />
        <div className="plans-sync-line plans-sync-line-mid" />
      </div>
    </article>
  );
}

export default function PlansPage() {
  const t = useTranslations("Workspace");
  const router = useRouter();
  const { showToast } = useToast();
  const { isMeHydrated, me, session } = useAppSession();
  const [plans, setPlans] = useState<PlanSummary[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [localPlans, setLocalPlans] = useState<PlanSummary[] | null>(null);
  const [activePlanId, setActivePlanId] = useState<string | null>(null);
  const [isSettingActivePlanId, setIsSettingActivePlanId] = useState<string | null>(null);
  const [overlapConflictPlan, setOverlapConflictPlan] = useState<PlanSummary | null>(null);
  const [isArchiveOpen, setIsArchiveOpen] = useState(false);
  // The plan whose Manage sheet is open, if any.
  const [managedPlanId, setManagedPlanId] = useState<string | null>(null);
  // The active camp's phase, from the Today command; extra, so never awaited.
  const [activePhase, setActivePhase] = useState<{ planId: string; phase: string } | null>(null);
  const latestTokenRef = useRef(session?.access_token);

  useEffect(() => {
    latestTokenRef.current = session?.access_token;
  }, [session?.access_token]);

  const visiblePlans = useMemo(() => {
    const sourcePlans = localPlans ?? plans;
    return [...sourcePlans].sort((left, right) => new Date(right.created_at).getTime() - new Date(left.created_at).getTime());
  }, [localPlans, plans]);
  const explicitActivePlan = activePlanId ? visiblePlans.find((plan) => plan.plan_id === activePlanId) ?? null : null;
  const activePlan = explicitActivePlan && canSetActive(explicitActivePlan) ? explicitActivePlan : null;
  const intakeSource = getIntakeSource(me);
  const heldForReviewPlans = visiblePlans.filter(isHeldForAdminReviewPlan);
  const archivedPlans = getArchivedPlans(visiblePlans);
  const otherSavedPlans = visiblePlans.filter((plan) => plan.plan_id !== activePlan?.plan_id && !isArchivedPlan(plan.status));
  const hasPlans = visiblePlans.length > 0;
  const managedPlan = managedPlanId ? visiblePlans.find((plan) => plan.plan_id === managedPlanId) ?? null : null;
  const tacticalStyle = getOptionLabels(TACTICAL_STYLE_OPTIONS, me?.profile?.tactical_style ?? [])[0] ?? null;
  const phase = activePlan && activePhase?.planId === activePlan.plan_id ? activePhase.phase : null;

  const loadPlans = useCallback(async () => {
    const token = session?.access_token;
    if (!token) {
      return;
    }
    setIsLoading(true);
    setError(null);
    try {
      const [nextPlans, active] = await Promise.all([
        listPlans(token),
        getActivePlan(token).catch((activeError) => {
          if (activeError instanceof ApiError && activeError.status === 404) {
            return null;
          }
          throw activeError;
        }),
      ]);
      // Ignore results from a request that the current session has moved past.
      if (latestTokenRef.current !== token) {
        return;
      }
      setPlans(nextPlans);
      setActivePlanId(active?.plan_id ?? null);
    } catch (plansError) {
      if (latestTokenRef.current !== token) {
        return;
      }
      const message = plansError instanceof Error ? plansError.message : "";
      setError(message.includes("401") || message.toLowerCase().includes("session")
        ? "Session expired. Sign in again."
        : "Connection issue. Try again in a minute.");
    } finally {
      if (latestTokenRef.current === token) {
        setIsLoading(false);
      }
    }
  }, [session?.access_token]);

  useEffect(() => {
    void loadPlans();
  }, [loadPlans]);

  useEffect(() => {
    if (!archivedPlans.length) {
      setIsArchiveOpen(false);
    }
  }, [archivedPlans.length]);

  useEffect(() => {
    const token = session?.access_token;
    if (!token) return;
    let cancelled = false;
    getToday(token)
      .then((command) => {
        const planId = command.active_plan?.id;
        const rawPhase = command.active_plan?.phase;
        if (!cancelled && planId && rawPhase) {
          setActivePhase({ planId, phase: humanizeIfRawEnum(rawPhase) });
        }
      })
      // The phase is a nicety: without it the card simply leaves it out.
      .catch(() => undefined);
    return () => {
      cancelled = true;
    };
  }, [session?.access_token]);

  function handlePlanDeleted(planId: string) {
    setLocalPlans((current) => {
      const source = current ?? plans;
      return source.filter((currentPlan) => currentPlan.plan_id !== planId);
    });
    router.refresh();
  }

  function handlePlanRenamed(updatedPlan: PlanSummary) {
    setLocalPlans((current) => {
      const source = current ?? plans;
      return source.map((currentPlan) => (currentPlan.plan_id === updatedPlan.plan_id ? { ...currentPlan, ...updatedPlan } : currentPlan));
    });
    router.refresh();
  }

  async function activatePlan(plan: PlanSummary, overlapAction?: ActivePlanOverlapAction): Promise<void> {
    const token = session?.access_token;
    if (!token || !canSetActive(plan)) {
      return;
    }
    setIsSettingActivePlanId(plan.plan_id);
    try {
      const active = await setActivePlan(token, plan.plan_id, { overlapAction });
      setActivePlanId(active.plan_id);
      setOverlapConflictPlan(null);
      showToast("Active plan updated.", { tone: "success" });
      await loadPlans();
      requestXpRefresh();
      router.refresh();
    } catch (activeError) {
      if (!overlapAction && isActivePlanOverlapError(activeError)) {
        setOverlapConflictPlan(plan);
        return;
      }
      const message = activeError instanceof Error ? activeError.message : "Unable to set active plan.";
      showToast(message, { tone: "error" });
    } finally {
      setIsSettingActivePlanId(null);
    }
  }

  async function handleSetActive(plan: PlanSummary): Promise<void> {
    await activatePlan(plan);
  }

  async function handleOverlapConfirm(action: ActivePlanOverlapAction): Promise<void> {
    if (!overlapConflictPlan) {
      return;
    }
    await activatePlan(overlapConflictPlan, action);
  }

  const isPlanListLoading = isLoading;
  const isProfileLoading = !isMeHydrated;

  return (
    <RequireAuth>
      <section className={styles.page}>
        <header className={styles.pageHeader}>
          <Link href="/history" className={styles.historyLink}>
            <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 19v-5m5 5V9m5 10V5m5 14V2" /></svg>
            View History <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7" /></svg>
          </Link>
          <h1 className={`athlete-motion-slot athlete-motion-header ${styles.pageTitle}`}>{t("planWorkspace")}</h1>
          <p className={styles.pageSubtitle}>Build, manage and add to your training.</p>
        </header>
        <div className={actionStyles.actions}>
          <LogTraining accessToken={session?.access_token ?? null} variant="tile" />
          <TrainingLibraryLink variant="tile" />
        </div>

        {error ? (
          <div className="error-banner athlete-motion-slot athlete-motion-status" role="alert">
            <span>{error}</span>
            {error.includes("Session expired") ? null : (
              <button
                type="button"
                className="error-banner-retry"
                onClick={() => void loadPlans()}
                disabled={isLoading}
              >
                {isLoading ? t("retrying") : t("retry")}
              </button>
            )}
          </div>
        ) : null}

        {!isLoading && heldForReviewPlans.length > 0 ? (
          <HeldPlansReviewNotice plans={heldForReviewPlans} />
        ) : null}

        <div className="athlete-motion-slot athlete-motion-main">
          {isPlanListLoading ? (
            <PlansSyncState />
          ) : (
            <CurrentCampCard
              plan={activePlan}
              intake={intakeSource}
              tacticalStyle={tacticalStyle}
              phase={phase}
              onManage={() => setManagedPlanId(activePlan?.plan_id ?? null)}
            />
          )}
        </div>

        {isLoading ? (
          <div className={`athlete-motion-slot athlete-motion-main ${styles.section}`} aria-busy="true">
            <div className={styles.sectionHead}>
              <h2 className={styles.sectionTitle}>{t("previousPlans")}</h2>
              <span className={styles.sectionMeta}>{t("loading")}</span>
            </div>
            <div className="plan-history-list plans-history-list">
              <PlanHistoryRowSkeleton />
              <PlanHistoryRowSkeleton />
            </div>
          </div>
        ) : null}

        {!isLoading && hasPlans ? (
          <div className={`athlete-motion-slot athlete-motion-main ${styles.section}`}>
            <div className={styles.sectionHead}>
              <h2 className={styles.sectionTitle}>{t("previousPlans")}</h2>
              {otherSavedPlans.length ? (
                <span className={styles.sectionMeta}>{t("savedCount", { count: otherSavedPlans.length })}</span>
              ) : null}
            </div>
            {otherSavedPlans.length > 0 ? (
              <ul className={styles.rows}>
                {otherSavedPlans.map((plan) => (
                  <PlanRow
                    key={plan.plan_id}
                    plan={plan}
                    activePlanId={activePlanId}
                    onOpen={() => setManagedPlanId(plan.plan_id)}
                  />
                ))}
              </ul>
            ) : (
              <p className="muted">No other saved plans.</p>
            )}

            {archivedPlans.length ? (
              <>
                <button
                  type="button"
                  className={styles.archiveToggle}
                  onClick={() => setIsArchiveOpen((current) => !current)}
                  aria-expanded={isArchiveOpen}
                  aria-controls="plans-archive"
                >
                  {t("archivedCount", { count: archivedPlans.length })}
                  <span className={styles.toggleChevron} aria-hidden="true" />
                </button>
                {isArchiveOpen ? (
                  <ul id="plans-archive" className={styles.rows} aria-label={t("olderPlans")}>
                    {archivedPlans.map((plan) => (
                      <PlanRow
                        key={plan.plan_id}
                        plan={plan}
                        activePlanId={activePlanId}
                        onOpen={() => setManagedPlanId(plan.plan_id)}
                      />
                    ))}
                  </ul>
                ) : null}
              </>
            ) : null}
          </div>
        ) : null}

        <div className={`athlete-motion-slot athlete-motion-main ${styles.section}`}>
          {isProfileLoading ? null : <AthleteProfileRow me={me} />}
        </div>

        <FeaturedDrill accessToken={session?.access_token ?? null} />

        {managedPlan ? (
          <PlanManageSheet
            key={managedPlan.plan_id}
            plan={managedPlan}
            activePlanId={activePlanId}
            accessToken={session?.access_token ?? null}
            isSettingActive={isSettingActivePlanId === managedPlan.plan_id}
            onSetActive={handleSetActive}
            onPlanRenamed={handlePlanRenamed}
            onPlanDeleted={handlePlanDeleted}
            onClose={() => setManagedPlanId(null)}
          />
        ) : null}

        {overlapConflictPlan ? (
          <PlanSwitchDialog
            plan={overlapConflictPlan}
            isPending={isSettingActivePlanId === overlapConflictPlan.plan_id}
            onConfirm={handleOverlapConfirm}
            onCancel={() => setOverlapConflictPlan(null)}
          />
        ) : null}
      </section>
    </RequireAuth>
  );
}

web/components/exercise-demo.tsx:
"use client";

import {
  createContext,
  useContext,
  useEffect,
  useRef,
  useState,
  useSyncExternalStore,
  type ReactNode,
} from "react";

import {
  YOUTUBE_NOCOOKIE_HOST,
  demoFullVideoUrl,
  demoSegmentLabel,
  demoThumbnailUrl,
  hasWatchedDemo,
  loadYouTubeIframeApi,
  markDemoWatched,
  subscribeDemoWatched,
  type YouTubePlayer,
} from "@/lib/exercise-demo";
import type { ExerciseMedia } from "@/lib/types";

// ---------------------------------------------------------------------------
// Plan-level media map, relayed to the exercise rows like the rehab label
// policy: Plan Detail mounts it through StructuredPlanRenderer, Today mounts it
// around its standalone SessionCards.
// ---------------------------------------------------------------------------

const ExerciseMediaContext = createContext<Record<string, ExerciseMedia> | null>(null);

export function ExerciseMediaProvider({
  media,
  children,
}: {
  media?: Record<string, ExerciseMedia> | null;
  children: ReactNode;
}) {
  return <ExerciseMediaContext.Provider value={media ?? null}>{children}</ExerciseMediaContext.Provider>;
}

/** Response-map prefix for blocks resolved on canonical identity (server: EXERCISE_KEY_MEDIA_PREFIX). */
export const EXERCISE_KEY_MEDIA_PREFIX = "exercise:";

/**
 * The block's demo. A block with a canonical `exercise_key` resolves on that
 * identity only, so rewording its display name never loses or swaps its video;
 * a legacy block without one falls back to its display name.
 */
export function useExerciseMedia(
  displayName: string | null | undefined,
  exerciseKey?: string | null,
): ExerciseMedia | null {
  const map = useContext(ExerciseMediaContext);
  if (!map) return null;
  const key = exerciseKey?.trim();
  const media = key ? map[`${EXERCISE_KEY_MEDIA_PREFIX}${key}`] : displayName ? map[displayName] : undefined;
  return media && typeof media.video_id === "string" && media.video_id ? media : null;
}

// ---------------------------------------------------------------------------
// Demo player
// ---------------------------------------------------------------------------

type DemoMode = "facade" | "loading" | "playing" | "paused" | "error";

/** How often the loop guard checks the playhead against the segment end. */
const LOOP_POLL_MS = 250;

export function ExerciseDemo({
  media,
  exerciseName,
  leadCue,
  onLeadCuePinnedChange,
}: {
  media: ExerciseMedia;
  exerciseName: string;
  /** First coaching cue, pinned under the video while the demo leads the row. */
  leadCue?: string | null;
  /** Tells the row whether the lead cue is shown here, so the cue list below
   * does not print it twice. */
  onLeadCuePinnedChange?: (pinned: boolean) => void;
}) {
  const [mode, setMode] = useState<DemoMode>("facade");
  // Server snapshot is "not watched", so SSR and hydration agree; the client
  // then reads this device's memory.
  const watched = useSyncExternalStore(
    subscribeDemoWatched,
    () => hasWatchedDemo(media.video_id),
    () => false,
  );
  const [slow, setSlow] = useState(false);
  const [muted, setMuted] = useState(true);
  const [thumbFailed, setThumbFailed] = useState(false);
  // iPhone Safari cannot fullscreen an iframe, so the control only shows
  // where the browser supports it.
  const [canFullscreen] = useState(
    () => typeof document !== "undefined" && document.fullscreenEnabled === true,
  );
  const mountRef = useRef<HTMLDivElement | null>(null);
  const playerRef = useRef<YouTubePlayer | null>(null);
  const loopTimerRef = useRef<number | null>(null);
  // PLAYING fires again on every loop restart; record the watch once.
  const watchRecordedRef = useRef(false);

  const start = Math.max(0, Math.floor(media.start_s || 0));
  const end = media.end_s != null && media.end_s > start ? Math.floor(media.end_s) : null;
  const segment = demoSegmentLabel(media);
  const isCoach = media.source === "coach";
  const channel = media.channel_title?.trim() || null;
  // Only an explicit "portrait" changes the frame: null, undefined and
  // "landscape" all render the existing 16:9 layout untouched.
  const portrait = media.orientation === "portrait";
  const playerActive = mode === "loading" || mode === "playing" || mode === "paused";
  const compact = watched && mode === "facade";
  const pinLeadCue = Boolean(leadCue) && !compact && mode !== "error";

  useEffect(() => {
    onLeadCuePinnedChange?.(pinLeadCue);
  }, [onLeadCuePinnedChange, pinLeadCue]);

  useEffect(() => {
    if (!playerActive || playerRef.current || !mountRef.current) return;
    let cancelled = false;
    const host = mountRef.current;

    loadYouTubeIframeApi()
      .then((YT) => {
        if (cancelled) return;
        const target = document.createElement("div");
        host.replaceChildren(target);
        playerRef.current = new YT.Player(target, {
          host: YOUTUBE_NOCOOKIE_HOST,
          videoId: media.video_id,
          width: "100%",
          height: "100%",
          playerVars: {
            autoplay: 1,
            // Muted so autoplay after the tap is allowed on iOS; the athlete
            // can turn sound on for coach demos that talk through the rep.
            mute: 1,
            playsinline: 1,
            controls: 0,
            // Keyboard shortcuts and fullscreen stay enabled; only the control
            // bar is swapped for the row's own controls below the frame.
            fs: 1,
            rel: 0,
            iv_load_policy: 3,
            start,
            ...(end != null ? { end } : {}),
          },
          events: {
            onReady: (event) => {
              if (cancelled) return;
              event.target.playVideo();
            },
            onStateChange: (event) => {
              if (cancelled) return;
              if (event.data === YT.PlayerState.PLAYING) {
                setMode("playing");
                if (!watchRecordedRef.current) {
                  watchRecordedRef.current = true;
                  markDemoWatched(media.video_id);
                }
              } else if (event.data === YT.PlayerState.PAUSED) {
                setMode("paused");
              } else if (event.data === YT.PlayerState.ENDED) {
                // Loop the segment rather than falling through to YouTube's
                // end screen of unrelated videos.
                event.target.seekTo(start, true);
                event.target.playVideo();
              }
            },
            onError: () => {
              if (cancelled) return;
              // The error state drops the frame, so release the player now
              // rather than when the row collapses.
              try {
                playerRef.current?.destroy();
              } catch {
                // Already torn down.
              }
              playerRef.current = null;
              setMode("error");
            },
          },
        });
      })
      .catch(() => {
        if (!cancelled) setMode("error");
      });

    return () => {
      cancelled = true;
    };
  }, [end, media.video_id, playerActive, start]);

  // Segment loop guard: `end` only fires ENDED on the first pass, and a seek
  // (Replay) can clear it, so the playhead is also checked while playing.
  useEffect(() => {
    if (mode !== "playing" || end == null) return;
    loopTimerRef.current = window.setInterval(() => {
      const player = playerRef.current;
      if (player && player.getCurrentTime() >= end - 0.15) {
        player.seekTo(start, true);
      }
    }, LOOP_POLL_MS);
    return () => {
      if (loopTimerRef.current != null) window.clearInterval(loopTimerRef.current);
      loopTimerRef.current = null;
    };
  }, [end, mode, start]);

  // Collapsing the row unmounts the demo: stop and release the player.
  useEffect(
    () => () => {
      try {
        playerRef.current?.destroy();
      } catch {
        // The frame may already be gone (error state removed it).
      }
      playerRef.current = null;
    },
    [],
  );

  const replay = () => {
    const player = playerRef.current;
    if (!player) return;
    player.seekTo(start, true);
    player.playVideo();
  };

  const togglePlay = () => {
    const player = playerRef.current;
    if (!player) return;
    if (mode === "playing") player.pauseVideo();
    else player.playVideo();
  };

  const toggleSlow = () => {
    const next = !slow;
    playerRef.current?.setPlaybackRate(next ? 0.5 : 1);
    setSlow(next);
  };

  const enterFullscreen = () => {
    const frame = mountRef.current?.querySelector("iframe");
    frame?.requestFullscreen?.().catch(() => {
      // Refused (no user activation, or the browser blocks it): stay inline.
    });
  };

  const toggleSound = () => {
    const player = playerRef.current;
    if (!player) return;
    if (muted) player.unMute();
    else player.mute();
    setMuted(!muted);
  };

  if (mode === "error") {
    return (
      <div className="ex-demo-unavailable" role="status">
        <span>Video unavailable here. Use the cues below.</span>
        <a href={demoFullVideoUrl(media)} target="_blank" rel="noopener noreferrer">
          Watch on YouTube
        </a>
      </div>
    );
  }

  if (compact) {
    return (
      <button
        type="button"
        className="ex-demo-replay-strip"
        onClick={() => setMode("loading")}
        aria-label={`Replay ${exerciseName} demo`}
      >
        <span className="ex-demo-replay-thumb" aria-hidden="true">
          {thumbFailed ? null : (
            // eslint-disable-next-line @next/next/no-img-element -- remote YouTube thumbnail, not a local asset
            <img src={demoThumbnailUrl(media.video_id, "mq")} alt="" loading="lazy" onError={() => setThumbFailed(true)} />
          )}
          <span className="ex-demo-play-glyph ex-demo-play-glyph-sm" />
        </span>
        <span className="ex-demo-replay-label">Replay demo</span>
        <span className="ex-demo-replay-meta">Watched</span>
      </button>
    );
  }

  return (
    <div className="ex-demo" data-mode={mode} data-orientation={portrait ? "portrait" : undefined}>
      <div className="ex-demo-frame">
        {playerActive ? (
          <div ref={mountRef} className="ex-demo-player" />
        ) : (
          <button
            type="button"
            className="ex-demo-facade"
            onClick={() => setMode("loading")}
            aria-label={`Play ${exerciseName} demo`}
          >
            {thumbFailed ? null : (
              // eslint-disable-next-line @next/next/no-img-element -- remote YouTube thumbnail, not a local asset
              <img
                src={demoThumbnailUrl(media.video_id)}
                alt=""
                loading="lazy"
                className="ex-demo-thumb"
                onError={() => setThumbFailed(true)}
              />
            )}
            <span className="ex-demo-play-glyph" aria-hidden="true" />
          </button>
        )}
      </div>

      {/* Nothing is drawn over the frame: labels and attribution sit under
          it, and the full video is one tap away before and during playback. */}
      <div className="ex-demo-caption">
        {isCoach ? <span className="ex-demo-badge">Coach demo</span> : null}
        <span className="ex-demo-meta">
          {["Demo", segment, channel].filter(Boolean).join(" · ")}
        </span>
        <a className="ex-demo-external" href={demoFullVideoUrl(media)} target="_blank" rel="noopener noreferrer">
          Watch on YouTube
        </a>
      </div>

      {playerActive ? (
        <div className="ex-demo-controls" role="group" aria-label="Demo controls">
          <button type="button" className="ex-demo-control" onClick={togglePlay} disabled={mode === "loading"}>
            {mode === "playing" ? "Pause" : "Play"}
          </button>
          <button type="button" className="ex-demo-control" onClick={replay} disabled={mode === "loading"}>
            Replay
          </button>
          <button
            type="button"
            className="ex-demo-control"
            onClick={toggleSlow}
            aria-pressed={slow}
            disabled={mode === "loading"}
          >
            0.5×
          </button>
          <button
            type="button"
            className="ex-demo-control"
            onClick={toggleSound}
            aria-pressed={!muted}
            disabled={mode === "loading"}
          >
            {muted ? "Sound off" : "Sound on"}
          </button>
          {canFullscreen ? (
            <button type="button" className="ex-demo-control" onClick={enterFullscreen} disabled={mode === "loading"}>
              Full screen
            </button>
          ) : null}
        </div>
      ) : null}

      {pinLeadCue ? (
        <p className="ex-demo-lead-cue">
          <span className="sp-stat-label">Key cue</span>
          {leadCue}
        </p>
      ) : null}
    </div>
  );
}

web/components/today/injury-detail-sheet:
"use client";

import { useEffect, useId, useRef, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { lockOverlayScroll } from "@/lib/overlay-scroll-lock";

/** Injury details stay off the daily card; reuse the app's iOS scroll lock.
 * `variant="screen"` fills the viewport for a full screen (Today's session
 * preview). Sheets stack: only the topmost one answers Escape and Tab. */
export function InjuryDetailSheet({ title, children, onClose, busy = false, variant = "sheet", closeLabel = "Close" }: {
  title: string; children: ReactNode; onClose: () => void; busy?: boolean;
  variant?: "sheet" | "screen"; closeLabel?: string;
}) {
  const titleId = useId();
  const panel = useRef<HTMLDivElement>(null);
  const state = useRef({ busy, onClose });
  useEffect(() => { state.current = { busy, onClose }; }, [busy, onClose]);
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null;
    const release = lockOverlayScroll();
    panel.current?.focus({ preventScroll: true });
    function keydown(event: KeyboardEvent) {
      const dialogs = document.querySelectorAll('[role="dialog"][aria-modal="true"]');
      if (dialogs[dialogs.length - 1] !== panel.current) return;
      if (event.key === "Escape") {
        event.preventDefault();
        if (!state.current.busy) state.current.onClose();
      }
      if (event.key !== "Tab") return;
      const controls = Array.from(panel.current?.querySelectorAll<HTMLElement>(
        'button:not(:disabled), select:not(:disabled), input:not(:disabled), summary, a[href], [tabindex="0"]',
      ) ?? []).filter(control => {
        const details = control.closest("details");
        return !details || details.open || control.tagName === "SUMMARY";
      });
      const first = controls[0], last = controls.at(-1);
      if (!first) { event.preventDefault(); panel.current?.focus(); }
      else if (event.shiftKey && (document.activeElement === first || document.activeElement === panel.current)) {
        event.preventDefault(); last?.focus();
      } else if (!event.shiftKey && (document.activeElement === last || document.activeElement === panel.current)) {
        event.preventDefault(); first.focus();
      }
    }
    document.addEventListener("keydown", keydown);
    return () => { document.removeEventListener("keydown", keydown); release(); previous?.focus({ preventScroll: true }); };
  }, []);
  if (typeof document === "undefined") return null;
  return createPortal(<div className="injury-sheet-backdrop" data-variant={variant} onClick={() => { if (!busy) onClose(); }}>
    <div className="injury-sheet" data-variant={variant} ref={panel} role="dialog" aria-modal="true" aria-labelledby={titleId}
      aria-busy={busy} tabIndex={-1} onClick={event => event.stopPropagation()}>
      <div className="injury-sheet-header"><h2 id={titleId}>{title}</h2>
        <button type="button" className="injury-sheet-close" aria-label={closeLabel} disabled={busy} onClick={onClose}>
          <svg viewBox="0 0 24 24" aria-hidden="true"><path d={variant === "screen" ? "m15 5-7 7 7 7" : "m6 6 12 12M6 18 18 6"} /></svg>
        </button>
      </div>
      {children}
    </div>
  </div>, document.body);
}

export function InjuryChevron() {
  return <svg className="injury-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7" /></svg>;
}

